    fn function_call_arguments_delta(item_id: &str, delta: &str) -> Vec<u8> {
        frame(json!({
            "type": "response.function_call_arguments.delta",
            "sequence_number": 0,
            "item_id": item_id,
            "output_index": 0,
            "delta": delta
        }))
    }

